<div class="split-panels"><section class="panel"><div class="panel-heading"><div><h2>Team members</h2><p>User directory (latest 100).</p></div><span class="pill"><?= count($users) ?> VISIBLE</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>NAME</th><th>EMAIL</th><th>GROUPS</th><th>STATUS</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?= esc($u['name']) ?></b></td><td><?= esc($u['email']) ?></td><td><?= esc($u['groups']??'-') ?></td><td><span class="pill <?= $u['is_active']?'pill-green':'' ?>"><?= $u['is_active']?'ACTIVE':'DISABLED' ?></span></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Create user</h2></div><form action="/admin/users/create" method="post" class="form-stack"><input type="hidden" name="_csrf" value="<?= esc(\Brightery\Core\App::get()->service(\Brightery\Core\Security::class)->csrf()) ?>"><label class="bf-field"><span>Full name</span><input name="name" required maxlength="160" placeholder="Team member"></label><label class="bf-field"><span>Email address</span><input name="email" type="email" required placeholder="person@example.com"></label><label class="bf-field"><span>Password (12+ characters)</span><input name="password" type="password" minlength="12" autocomplete="new-password" required></label><label class="bf-field"><span>Assign group</span><select name="group_id" required><?php foreach($groups as $g):?><option value="<?= (int)$g['id'] ?>"><?= esc($g['name']) ?></option><?php endforeach;?></select></label><button type="submit" class="btn btn-primary">Create account →</button></form></section></div>
